package fraymus.workspace;

import org.json.*;
import java.util.*;

final class MapReport {
    static JSONArray charts(JSONObject record,JSONObject run){
        var map=record.getJSONObject("definition");var path=map.getJSONArray("path");var target=MapDefinition.position(map,path.getInt(path.length()-1),map.getDouble("cellSizeM"));var samples=run.getJSONArray("samples");double duration=run.getJSONObject("final").getDouble("timeS"),travel=0;double[] before=null;double[][] values=new double[6][samples.length()];double[] maxima=new double[6];Arrays.fill(maxima,.1);
        for(int i=0;i<samples.length();i++){var sample=samples.getJSONObject(i);var position=SpatialScene.vector(sample.getJSONArray("position"),30);if(before!=null)travel+=ObserverGeometry.norm(ObserverGeometry.sub(position,before));before=position;values[0][i]=Math.hypot(position[0]-target[0],position[2]-target[2]);values[1][i]=ObserverGeometry.norm(SpatialScene.vector(sample.getJSONArray("velocity"),30));values[2][i]=ObserverGeometry.norm(SpatialScene.vector(sample.getJSONArray("force"),30));values[3][i]=sample.getInt("contacts");values[4][i]=sample.getDouble("effortNs");values[5][i]=travel;for(int kind=0;kind<6;kind++)maxima[kind]=Math.max(maxima[kind],values[kind][i]);}
        var result=new JSONArray();String[] labels={"Distance to goal · m","Speed · m/s","Applied force · N","Native contacts","Integrated force effort · N·s","Travelled distance · m"};for(int kind=0;kind<6;kind++){var points=new JSONArray();for(int i=0;i<samples.length();i++)points.put(new JSONArray(new double[]{Procedural.round(40+720*samples.getJSONObject(i).getDouble("timeS")/duration),Procedural.round(260-220*values[kind][i]/maxima[kind])}));result.put(new JSONObject().put("mode",labels[kind]).put("maximum",maxima[kind]).put("durationS",duration).put("values",new JSONArray(values[kind])).put("points",points));}return result;
    }
    static JSONObject report(JSONObject goal,JSONObject map,JSONObject run){var csv=new StringBuilder("tick,time_s,x_m,y_m,z_m,vx_mps,vy_mps,vz_mps,fx_N,fz_N,contacts,wall_contacts,path_index\n");for(Object raw:run.getJSONArray("samples")){var s=(JSONObject)raw;csv.append(s.getInt("tick")).append(',').append(s.getDouble("timeS"));for(String key:List.of("position","velocity"))for(Object v:s.getJSONArray(key))csv.append(',').append(v);csv.append(',').append(s.getJSONArray("force").getDouble(0)).append(',').append(s.getJSONArray("force").getDouble(2)).append(',').append(s.getInt("contacts")).append(',').append(s.getInt("wallContacts")).append(',').append(s.getInt("pathIndex")).append('\n');}return new JSONObject().put("title","Verified playable map · "+map.getString("title")).put("files",new JSONObject().put("index.html",HTML).put("map.json",map.toString()).put("run.json",run.toString()).put("charts.json",charts(map,run).toString()).put("trace.csv",csv.toString())).put("sources",new JSONArray(List.of("map:"+map.getString("id")+":"+map.getString("sha256"),"native-map-run:"+run.getString("id"))));}
    static JSONArray checks(JSONObject goal,JSONObject run){return new JSONArray().put(new JSONObject().put("selector","#map-result").put("expectText","Native traversal verified")).put(new JSONObject().put("selector","#map-samples").put("expectText",String.valueOf(run.getJSONArray("samples").length()))).put(new JSONObject().put("selector","#chart-label").put("expectText","Distance to goal · m")).put(new JSONObject().put("selector","#chart-mode").put("action","click")).put(new JSONObject().put("selector","#chart-label").put("expectText","Speed · m/s")).put(new JSONObject().put("selector","#chart-reset").put("action","click")).put(new JSONObject().put("selector","#chart-label").put("expectText","Distance to goal · m")).put(new JSONObject().put("selector","#map-scope").put("expectText",MapDefinition.SCOPE));}
    static JSONObject verifyView(JSONObject record,JSONObject run,JSONObject actual){
        var expected=charts(record,run);var frames=actual.getJSONArray("frames");if(frames.length()!=expected.length()||!actual.getString("mode").equals(expected.getJSONObject(0).getString("mode")))throw new IllegalStateException("Observe all native metric charts and return to the original view");double maximum=0;int count=0;
        for(int f=-1;f<frames.length();f++){var observed=f<0?actual:frames.getJSONObject(f);var chart=expected.getJSONObject(Math.max(0,f));var points=observed.getJSONArray("points");var target=chart.getJSONArray("points");if(!observed.getString("mode").equals(chart.getString("mode"))||points.length()!=target.length())throw new IllegalStateException("Native chart mode/count differs from original trace");for(int i=0;i<points.length();i++)for(int k=0;k<2;k++){double error=Math.abs(points.getJSONArray(i).getDouble(k)-target.getJSONArray(i).getDouble(k));if(!Double.isFinite(error))throw new IllegalStateException("Nonfinite chart coordinate");maximum=Math.max(maximum,error);}if(f>=0)count+=points.length();}
        if(maximum>.002)throw new IllegalStateException("Actual native map metric differs beyond0.002 SVG units");return new JSONObject().put("passed",true).put("frames",frames.length()).put("observedPoints",count).put("maxError",maximum);
    }
    static final String HTML="""
<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Playable map evidence</title><style>*{box-sizing:border-box}body{margin:0;background:#102529;color:#e8f4ef;font:15px/1.6 system-ui;overflow-wrap:anywhere}main{padding:24px;max-width:1100px;margin:auto}h1{font-size:30px}.cards,.controls{display:flex;gap:12px;flex-wrap:wrap}.cards>div{flex:1;min-width:120px;background:#193b3d;padding:14px;border-radius:10px}b{display:block;font-size:22px}button,a{color:#d8f5e9}button{background:#285749;border:1px solid #83b8a5;border-radius:8px;padding:10px;font:inherit}svg{width:100%;height:auto;background:#f1f6ef;border-radius:10px;margin:16px 0}.grid{max-width:520px}pre{white-space:pre-wrap;background:#193b3d;padding:12px;border-radius:8px}img{max-width:180px;image-rendering:pixelated;width:100%}#scope{color:#a9d8c7}</style><main><p>FRAYNIX / ORIGINAL IMAGE RULES / NATIVE PHYSICAL OUTCOMES</p><h1 id="map-result">Loading verified evidence…</h1><p id="map-scope"></p><div class="cards"><div><b id="map-samples"></b>native samples</div><div><b id="map-error"></b>endpoint error · m</div><div><b id="map-contacts"></b>actual contacts</div><div><b id="map-route"></b>waypoints reached</div></div><p id="source"></p><img id="reference" hidden alt="Original palette-map reference"><svg class="grid" id="map-grid" aria-label="Original generated cells and measured native route"></svg><div class="controls"><button id="chart-mode">Next metric</button><button id="chart-reset">Reset chart</button><strong id="chart-label"></strong></div><svg viewBox="0 0 800 300" id="native-chart" aria-label="Measured native history"><path d="M40 20V260H760" stroke="#527869" fill="none"/><polyline id="native-trace" stroke="#176c5a" stroke-width="2" fill="none"/></svg><p id="scale"></p><h2>Generation, compilation and physical metrics</h2><pre id="metrics"></pre><details><summary>Original source and retained dimensional structure</summary><pre id="provenance"></pre></details><p><a href="map.json" download>Map and original source JSON</a> · <a href="run.json" download>Actual run JSON</a> · <a href="trace.csv" download>Native trace CSV</a></p><p>Java computes and verifies these outcomes. Procedure retention is not LLM-weight training or evidence of additional physical dimensions.</p></main><script>
(async()=>{const [record,run,charts]=await Promise.all(['map.json','run.json','charts.json'].map(async f=>(await fetch(f)).json()));const m=record.definition,v=run.verification,$=id=>document.getElementById(id),ns='http://www.w3.org/2000/svg';$('map-result').textContent=v.passed?'Native traversal verified':'Native traversal failed';$('map-scope').textContent=m.scope;$('map-samples').textContent=run.samples.length;$('map-error').textContent=v.endpointErrorM.toFixed(6);$('map-contacts').textContent=v.contacts;$('map-route').textContent=v.waypointsReached+'/'+v.routeWaypoints;$('source').textContent=m.source.kind==='reference-image'?'Reference image SHA256 '+m.source.reference.imageSha256:'Original '+m.source.dimensions+'D dungeon · selected layers '+JSON.stringify(m.source.layers)+' · original cells retained';if(m.source.reference){$('reference').src='data:image/png;base64,'+m.source.reference.pngBase64;$('reference').hidden=false;}const svg=$('map-grid');svg.setAttribute('viewBox','0 0 '+m.width*12+' '+m.height*12);function shape(tag,attrs){const e=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,String(v));svg.append(e);}m.cells.forEach((t,i)=>shape('rect',{x:i%m.width*12,y:Math.floor(i/m.width)*12,width:12,height:12,fill:m.palette[t]}));shape('polyline',{points:run.samples.map(s=>((s.position[0]/m.cellSizeM+m.width/2)*12)+','+((s.position[2]/m.cellSizeM+m.height/2)*12)).join(' '),fill:'none',stroke:'#e45244','stroke-width':1.8});let mode=0;function draw(){const c=charts[mode];$('chart-label').textContent=c.mode;$('native-trace').setAttribute('points',c.points.map(p=>p.join(',')).join(' '));$('scale').textContent='Time0–'+c.durationS.toFixed(3)+' s · vertical0–'+c.maximum.toFixed(3)+' · every point from the actual native trace';}$('chart-mode').onclick=()=>{mode=(mode+1)%charts.length;draw();};$('chart-reset').onclick=()=>{mode=0;draw();};$('metrics').textContent=JSON.stringify({generation:m.generation,compilation:m.metrics,physics:v,disturbanceNs:run.disturbanceNs},null,2);$('provenance').textContent=JSON.stringify({mapSha256:record.sha256,sourceKind:m.source.kind,reference:m.source.reference?{sha256:m.source.reference.imageSha256,palette:m.source.reference.palette,frequencies:m.source.reference.frequencies,rules:m.source.reference.rules}:m.source},null,2);draw();})().catch(e=>{document.getElementById('map-result').textContent='Evidence loading failed: '+e.message;throw e;});
</script></html>
""";
}
